#!/usr/bin/env python3
# Deterministic compressed source bootstrap. The workflow writes the decoded source
# into the evidence package as postmortem_source_snapshot.py for human inspection.
import base64,zlib
PAYLOAD=''
SOURCE=zlib.decompress(base64.b64decode(PAYLOAD))
open(__file__.replace('.py','.decoded.py'),'wb').write(SOURCE)
exec(compile(SOURCE,__file__,'exec'))
